import { NotFoundError, ValidationError } from "../domain/errors";
import { createProject, Project, ProjectRepository } from "../domain/project";
import {
  assignTask,
  createTask,
  isTaskStatus,
  markTaskDone,
  Task,
  TaskFilter,
  TaskRepository,
  TaskStatus,
} from "../domain/task";
import { createUser, User, UserRepository } from "../domain/user";

export interface IdGenerator {
  next(): string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: string;
  assigneeId?: string;
}

export interface ListTasksInput {
  status?: string;
  assigneeId?: string;
}

export class UserService {
  constructor(private readonly users: UserRepository, private readonly ids: IdGenerator) {}

  create(name: string): User {
    const user = createUser(this.ids.next(), name);
    this.users.save(user);
    return user;
  }
}

export class TaskManagementService {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
  ) {}

  createProject(name: string): Project {
    const project = createProject(this.ids.next(), name);
    this.projects.save(project);
    return project;
  }

  getProject(projectId: string): Project {
    return this.requireProject(projectId);
  }

  addTask(projectId: string, input: CreateTaskInput): Task {
    this.requireProject(projectId);
    let dueDate: Date | undefined;
    if (input.dueDate !== undefined && input.dueDate !== null) {
      if (typeof input.dueDate !== "string") {
        throw new ValidationError("Task due date must be an ISO date string");
      }
      dueDate = new Date(input.dueDate);
    }
    let task = createTask({
      id: this.ids.next(),
      projectId,
      title: input.title,
      description: input.description ?? "",
      dueDate,
      status: input.status as TaskStatus | undefined,
    });
    if (input.assigneeId !== undefined && input.assigneeId !== null) {
      this.requireUser(input.assigneeId);
      task = assignTask(task, input.assigneeId);
    }
    this.tasks.save(task);
    return task;
  }

  assignTask(taskId: string, assigneeId: string): Task {
    const task = this.requireTask(taskId);
    this.requireUser(assigneeId);
    const updated = assignTask(task, assigneeId);
    this.tasks.save(updated);
    return updated;
  }

  listTasks(projectId: string, input: ListTasksInput): Task[] {
    this.requireProject(projectId);
    const filter: TaskFilter = {};
    if (input.status !== undefined) {
      if (!isTaskStatus(input.status)) {
        throw new ValidationError("Status filter must be one of: todo, in progress, done");
      }
      filter.status = input.status;
    }
    if (input.assigneeId !== undefined) {
      filter.assigneeId = input.assigneeId;
    }
    return this.tasks.findByProject(projectId, filter);
  }

  markDone(taskId: string): Task {
    const updated = markTaskDone(this.requireTask(taskId));
    this.tasks.save(updated);
    return updated;
  }

  private requireProject(id: string): Project {
    const project = this.projects.findById(id);
    if (!project) throw new NotFoundError(`Project ${id} not found`);
    return project;
  }

  private requireTask(id: string): Task {
    const task = this.tasks.findById(id);
    if (!task) throw new NotFoundError(`Task ${id} not found`);
    return task;
  }

  private requireUser(id: string): User {
    const user = this.users.findById(id);
    if (!user) throw new NotFoundError(`User ${id} not found`);
    return user;
  }
}

